using System;using System.IO;using System.Reflection;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using CodexStrip;
class EqualCardsTest {
 static void Check(StripWindow w){w.UpdateLayout();var cards=(Grid)typeof(StripWindow).GetField("cards",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(w);double width=((Button)cards.Children[0]).ActualWidth;foreach(Button card in cards.Children)if(Math.Abs(card.ActualWidth-width)>1)throw new Exception("unequal rendered card widths");for(int i=1;i<cards.ColumnDefinitions.Count;i+=2)if(Math.Abs(cards.ColumnDefinitions[i].Width.Value-10)>.01)throw new Exception("unequal gap: index="+i+" actual="+cards.ColumnDefinitions[i].ActualWidth+" configured="+cards.ColumnDefinitions[i].Width+" window="+w.ActualWidth);}
 [STAThread]static void Main(){var app=new Application();var w=new StripWindow(true){Width=1280,Height=286};app.MainWindow=w;w.Loaded+=async delegate{try{await Task.Delay(150);Check(w);w.Snapshot("work/equal-cards.png");w.ShowUsage();await Task.Delay(350);Check(w);w.ShowSettings();await Task.Delay(350);Check(w);w.ClosePanel();await Task.Delay(350);Check(w);w.Width=600;await Task.Delay(350);Check(w);File.WriteAllText("work/equal-cards-test.txt","PASS: rendered task cards equal within one layout pixel; 10px dedicated gap columns; normal/utility/close/compact layouts");}catch(Exception e){File.WriteAllText("work/equal-cards-test.txt",e.ToString());}finally{w.Close();}};app.Run(w);}
}
